const statusLabel = (status: Status) => statuses.find(([value]) => value === status)?.[1] ?? status;
const emptyPerson = () => ({ memberId: "", displayName: "", contact: "", outboundStatus: "unknown" as Status, outboundAddress: "", outboundLatitude: "", outboundLongitude: "", outboundSeats: "", returnStatus: "unknown" as Status, returnAddress: "", returnLatitude: "", returnLongitude: "", returnSeats: "", returnSameAsOutbound: true, notes: "" });
