type ColumnMapping = { name: string; contact: string; memberId: string; outboundStatus: string; outboundAddress: string; outboundLatitude: string; outboundLongitude: string; outboundSeats: string; returnStatus: string; returnAddress: string; returnLatitude: string; returnLongitude: string; returnSeats: string; notes: string };
