  async function run<T>(work: () => Promise<T>, message?: string): Promise<T | undefined> { setBusy(true); setNotice(null); try { const result = await work(); if (message) setNotice({ tone: "success", message }); return result; } catch (error) { setNotice({ tone: "error", message: (error as Error).message }); return undefined; } finally { setBusy(false); } }
  function chooseStage(next: Stage) { setStage(next); setDirection("outbound"); setSelectedOfferId(""); }
  async function choosePlan(id: string) { setDirection("outbound"); setStage("event"); setEditPlan(null); setAddPersonOpen(false); if (id && onOpenPlan) { onOpenPlan(id); return; } await run(() => refresh(id)); }
